class Solution:
    def linearRegression(self, X: List[List[float]], y: List[float]) -> List[float]:
        m = len(X[0]) + 1  # features plus bias column
        G = [[0.0] * m for _ in range(m)]
        v = [0.0] * m
        for row, target in zip(X, y):
            a = list(row) + [1.0]
            for i in range(m):
                v[i] += a[i] * target
                for j in range(m):
                    G[i][j] += a[i] * a[j]
        return self._solve(G, v)

    def _solve(self, G: List[List[float]], v: List[float]) -> List[float]:
        m = len(v)
        M = [G[i][:] + [v[i]] for i in range(m)]  # augmented matrix
        for col in range(m):
            pivot = max(range(col, m), key=lambda r: abs(M[r][col]))
            M[col], M[pivot] = M[pivot], M[col]
            for r in range(col + 1, m):
                factor = M[r][col] / M[col][col]
                if factor != 0.0:
                    for c in range(col, m + 1):
                        M[r][c] -= factor * M[col][c]
        theta = [0.0] * m
        for i in range(m - 1, -1, -1):
            s = M[i][m]
            for j in range(i + 1, m):
                s -= M[i][j] * theta[j]
            theta[i] = s / M[i][i]
        return theta

